/**
 * What is orderable through Dine: Prime bot vendors, items and prices.
 * Generated by extract-prime-menu.ts from the crawl; refresh it when Prime's
 * menu changes. Open/closed is a crawl-time snapshot, so callers that know the
 * live status should pass it in (see RecommendOptions.isVendorOpen).
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

export interface PrimeItem {
  name: string;
  /** Whole naira. */
  price: number;
}

export interface PrimeVendor {
  id: string;
  name: string;
  location: "inside_cafeteria" | "outside_cafeteria";
  open: boolean;
  description: string;
  items: PrimeItem[];
}

export interface PrimeMenu {
  source: { bot: string; crawledAt: string; run: string };
  vendors: PrimeVendor[];
}

const __dirname = path.dirname(fileURLToPath(import.meta.url));
let cached: PrimeMenu | null = null;

export function loadPrimeMenu(): PrimeMenu {
  cached ??= JSON.parse(fs.readFileSync(path.join(__dirname, "data/prime-menu.json"), "utf8")) as PrimeMenu;
  return cached;
}
